arguments.command:
cat << 'EOF' > /app/output/index.html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Leap Studio — Your Reinvention and Experience Partner</title>
    <style>
        @import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap');

        :root {
            --bg-color: #0A0A0A;
            --surface-color: #141414;
            --surface-hover: #1F1F1F;
            --text-primary: #FFFFFF;
            --text-secondary: #A0A0A0;
            --accent-color: #0055FF;
            --border-color: #2A2A2A;
            --nav-height: 80px;
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        body {
            font-family: 'Inter', sans-serif;
            background-color: var(--bg-color);
            color: var(--text-primary);
            line-height: 1.6;
            -webkit-font-smoothing: antialiased;
            overflow-x: hidden;
        }

        a {
            color: inherit;
            text-decoration: none;
            transition: color 0.3s ease;
        }

        a:hover {
            color: var(--text-primary);
        }

        button {
            background: none;
            border: none;
            color: inherit;
            font: inherit;
            cursor: pointer;
        }

        img {
            max-width: 100%;
            height: auto;
            display: block;
        }

        /* Utility */
        .container {
            max-width: 1400px;
            margin: 0 auto;
            padding: 0 5%;
        }

        .section {
            padding: 120px 0;
            border-bottom: 1px solid var(--border-color);
        }

        .section-header {
            margin-bottom: 60px;
        }

        .section-title {
            font-size: 3rem;
            font-weight: 700;
            letter-spacing: -0.03em;
            margin-bottom: 20px;
            line-height: 1.1;
        }

        .section-subtitle {
            font-size: 1.25rem;
            color: var(--text-secondary);
            max-width: 600px;
        }

        .cta-btn {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            background-color: var(--text-primary);
            color: var(--bg-color);
            padding: 16px 32px;
            font-weight: 600;
            border-radius: 4px;
            transition: all 0.3s ease;
            text-transform: uppercase;
            letter-spacing: 0.05em;
            font-size: 0.875rem;
        }

        .cta-btn:hover {
            background-color: var(--accent-color);
            color: var(--text-primary);
        }

        .cta-btn.outline {
            background-color: transparent;
            color: var(--text-primary);
            border: 1px solid var(--border-color);
        }

        .cta-btn.outline:hover {
            border-color: var(--text-primary);
            background-color: var(--text-primary);
            color: var(--bg-color);
        }

        /* Navigation */
        nav {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: var(--nav-height);
            display: flex;
            align-items: center;
            justify-content: space-between;
            padding: 0 5%;
            background-color: rgba(10, 10, 10, 0.8);
            backdrop-filter: blur(10px);
            z-index: 1000;
            border-bottom: 1px solid var(--border-color);
        }

        .logo {
            font-size: 1.5rem;
            font-weight: 700;
            letter-spacing: -0.05em;
        }

        .nav-links {
            display: flex;
            gap: 2rem;
            font-size: 0.875rem;
            font-weight: 500;
            color: var(--text-secondary);
        }

        .nav-links a:hover {
            color: var(--text-primary);
        }

        .nav-actions {
            display: flex;
            align-items: center;
            gap: 1.5rem;
        }

        .lang-selector {
            position: relative;
        }

        .lang-toggle {
            display: flex;
            align-items: center;
            gap: 0.5rem;
            font-size: 0.875rem;
            font-weight: 500;
            color: var(--text-secondary);
            padding: 8px;
        }

        .lang-toggle:hover {
            color: var(--text-primary);
        }

        .lang-menu {
            position: absolute;
            top: 100%;
            right: 0;
            background-color: var(--surface-color);
            border: 1px solid var(--border-color);
            border-radius: 4px;
            padding: 8px 0;
            min-width: 150px;
            display: none;
            flex-direction: column;
            box-shadow: 0 10px 30px rgba(0,0,0,0.5);
        }

        .lang-menu.active {
            display: flex;
        }

        .lang-menu button {
            padding: 10px 20px;
            text-align: left;
            font-size: 0.875rem;
            color: var(--text-secondary);
            width: 100%;
        }

        .lang-menu button:hover {
            background-color: var(--surface-hover);
            color: var(--text-primary);
        }

        /* Mobile Nav Toggle */
        .mobile-menu-btn {
            display: none;
            flex-direction: column;
            gap: 5px;
            padding: 10px;
        }

        .mobile-menu-btn span {
            width: 25px;
            height: 2px;
            background: var(--text-primary);
        }

        /* Hero */
        .hero {
            position: relative;
            height: 100vh;
            min-height: 700px;
            display: flex;
            align-items: center;
            overflow: hidden;
            background-color: #050505;
        }

        .hero-carousel {
            position: absolute;
            inset: 0;
            width: 100%;
            height: 100%;
        }

        .hero-slide {
            position: absolute;
            inset: 0;
            opacity: 0;
            transition: opacity 0.8s ease;
            display: flex;
            align-items: center;
            background-size: cover;
            background-position: center;
        }

        .hero-slide.active {
            opacity: 1;
            z-index: 1;
        }

        .hero-slide::after {
            content: '';
            position: absolute;
            inset: 0;
            background: linear-gradient(to right, rgba(0,0,0,0.9) 0%, rgba(0,0,0,0.4) 100%);
        }

        .hero-content {
            position: relative;
            z-index: 2;
            max-width: 800px;
            padding: 0 5%;
            transform: translateY(20px);
            opacity: 0;
            transition: all 0.8s ease 0.3s;
        }

        .hero-slide.active .hero-content {
            transform: translateY(0);
            opacity: 1;
        }

        .hero-title {
            font-size: 4.5rem;
            font-weight: 700;
            letter-spacing: -0.04em;
            line-height: 1.05;
            margin-bottom: 24px;
        }

        .hero-desc {
            font-size: 1.5rem;
            color: var(--text-secondary);
            margin-bottom: 40px;
            max-width: 600px;
        }

        .hero-controls {
            position: absolute;
            bottom: 40px;
            right: 5%;
            z-index: 10;
            display: flex;
            gap: 16px;
        }

        .hero-controls button {
            width: 48px;
            height: 48px;
            border-radius: 50%;
            border: 1px solid rgba(255,255,255,0.2);
            display: flex;
            align-items: center;
            justify-content: center;
            background: rgba(0,0,0,0.3);
            backdrop-filter: blur(4px);
            transition: all 0.3s;
        }

        .hero-controls button:hover {
            background: var(--text-primary);
            color: var(--bg-color);
        }

        /* Team Section */
        .region-tabs {
            display: flex;
            gap: 2rem;
            margin-bottom: 40px;
            border-bottom: 1px solid var(--border-color);
            overflow-x: auto;
            scrollbar-width: none;
        }

        .region-tabs::-webkit-scrollbar {
            display: none;
        }

        .region-tab {
            padding: 16px 0;
            font-size: 1.125rem;
            font-weight: 500;
            color: var(--text-secondary);
            position: relative;
            white-space: nowrap;
        }

        .region-tab.active {
            color: var(--text-primary);
        }

        .region-tab::after {
            content: '';
            position: absolute;
            bottom: -1px;
            left: 0;
            width: 100%;
            height: 2px;
            background-color: var(--accent-color);
            transform: scaleX(0);
            transition: transform 0.3s ease;
        }

        .region-tab.active::after {
            transform: scaleX(1);
        }

        .region-content {
            display: none;
            animation: fadeIn 0.5s ease;
        }

        .region-content.active {
            display: block;
        }

        @keyframes fadeIn {
            from { opacity: 0; transform: translateY(10px); }
            to { opacity: 1; transform: translateY(0); }
        }

        .team-grid {
            display: flex;
            gap: 2rem;
            overflow-x: auto;
            padding-bottom: 2rem;
            scroll-snap-type: x mandatory;
            scrollbar-width: none;
        }

        .team-grid::-webkit-scrollbar {
            display: none;
        }

        .team-card {
            min-width: 350px;
            flex: 1;
            background-color: var(--surface-color);
            border: 1px solid var(--border-color);
            border-radius: 8px;
            overflow: hidden;
            scroll-snap-align: start;
            display: flex;
            flex-direction: column;
            transition: transform 0.3s ease;
        }

        .team-card:hover {
            transform: translateY(-5px);
            border-color: #444;
        }

        .team-photo {
            height: 250px;
            background-color: #222;
            position: relative;
        }

        .team-photo img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            filter: grayscale(80%) contrast(1.2) brightness(0.8);
            transition: filter 0.3s;
        }

        .team-card:hover .team-photo img {
            filter: grayscale(0%) contrast(1) brightness(1);
        }

        .team-info {
            padding: 30px;
            flex: 1;
            display: flex;
            flex-direction: column;
        }

        .team-quote {
            font-size: 1.125rem;
            font-style: italic;
            margin-bottom: 24px;
            color: var(--text-primary);
            flex: 1;
            line-height: 1.5;
        }

        .team-quote::before {
            content: '"';
            color: var(--accent-color);
            font-size: 1.5rem;
            font-family: serif;
        }

        .team-quote::after {
            content: '"';
        }

        .team-meta {
            margin-bottom: 20px;
        }

        .team-name {
            font-size: 1.25rem;
            font-weight: 600;
        }

        .team-title {
            color: var(--text-secondary);
            font-size: 0.875rem;
            margin-top: 4px;
        }

        .team-contact {
            color: var(--accent-color);
            font-size: 0.875rem;
            font-weight: 500;
            display: inline-flex;
            align-items: center;
            gap: 8px;
        }

        .team-contact:hover {
            text-decoration: underline;
        }

        /* Work Showcase */
        .work-carousel {
            display: flex;
            gap: 24px;
            overflow-x: auto;
            scroll-snap-type: x mandatory;
            padding-bottom: 40px;
            scrollbar-width: none;
        }

        .work-carousel::-webkit-scrollbar {
            display: none;
        }

        .work-card {
            min-width: 450px;
            flex: 0 0 auto;
            scroll-snap-align: start;
            group: work;
        }

        .work-img {
            aspect-ratio: 16/10;
            background-color: var(--surface-color);
            border-radius: 8px;
            overflow: hidden;
            margin-bottom: 20px;
        }

        .work-img img {
            width: 100%;
            height: 100%;
            object-fit: cover;
            filter: brightness(0.7) grayscale(30%);
            transition: all 0.5s ease;
        }

        .work-card:hover .work-img img {
            filter: brightness(1) grayscale(0%);
            transform: scale(1.05);
        }

        .work-client {
            font-size: 0.875rem;
            text-transform: uppercase;
            letter-spacing: 0.05em;
            color: var(--text-secondary);
            margin-bottom: 8px;
        }

        .work-title {
            font-size: 1.5rem;
            font-weight: 600;
            line-height: 1.3;
        }

        /* CTA Banner */
        .cta-banner {
            background: linear-gradient(135deg, #050505 0%, #1a1a1a 100%);
            text-align: center;
            padding: 120px 5%;
            border-top: 1px solid var(--border-color);
            border-bottom: 1px solid var(--border-color);
        }

        .cta-banner .section-title {
            margin-bottom: 24px;
        }

        .cta-banner .section-subtitle {
            margin: 0 auto 40px;
        }

        /* Insights */
        .insights-grid {
            display: grid;
            grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
            gap: 32px;
        }

        .insight-card {
            background-color: var(--surface-color);
            border: 1px solid var(--border-color);
            border-radius: 8px;
            padding: 32px;
            display: flex;
            flex-direction: column;
            transition: border-color 0.3s;
        }

        .insight-card:hover {
            border-color: var(--text-secondary);
        }

        .insight-type {
            font-size: 0.75rem;
            text-transform: uppercase;
            letter-spacing: 0.1em;
            color: var(--accent-color);
            margin-bottom: 16px;
        }

        .insight-title {
            font-size: 1.25rem;
            font-weight: 600;
            margin-bottom: 32px;
            line-height: 1.4;
            flex: 1;
        }

        .insight-link {
            font-size: 0.875rem;
            font-weight: 500;
            display: inline-flex;
            align-items: center;
            gap: 8px;
        }

        .insight-link::after {
            content: '→';
            transition: transform 0.3s;
        }

        .insight-card:hover .insight-link::after {
            transform: translateX(5px);
        }

        /* Principles */
        .principles-grid {
            display: grid;
            grid-template-columns: repeat(2, 1fr);
            gap: 60px;
        }

        .principle-item {
            position: relative;
            padding-left: 60px;
        }

        .principle-num {
            position: absolute;
            top: -10px;
            left: 0;
            font-size: 3rem;
            font-weight: 700;
            color: var(--border-color);
            line-height: 1;
        }

        .principle-title {
            font-size: 1.5rem;
            font-weight: 600;
            margin-bottom: 16px;
        }

        .principle-desc {
            color: var(--text-secondary);
        }

        /* Footer */
        footer {
            background-color: #050505;
            padding: 80px 0 40px;
        }

        .footer-ctas {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 60px;
            margin-bottom: 80px;
            padding-bottom: 80px;
            border-bottom: 1px solid var(--border-color);
        }

        .footer-cta h3 {
            font-size: 1.5rem;
            font-weight: 600;
            margin-bottom: 24px;
            max-width: 400px;
        }

        .footer-bottom {
            display: flex;
            justify-content: space-between;
            align-items: center;
            color: var(--text-secondary);
            font-size: 0.875rem;
        }

        .footer-links {
            display: flex;
            gap: 2rem;
        }

        /* Cookie Banner */
        .cookie-banner {
            position: fixed;
            bottom: 24px;
            left: 24px;
            right: 24px;
            max-width: 600px;
            background-color: var(--surface-color);
            border: 1px solid var(--border-color);
            border-radius: 8px;
            padding: 24px;
            z-index: 2000;
            box-shadow: 0 20px 40px rgba(0,0,0,0.5);
            display: flex;
            flex-direction: column;
            gap: 16px;
            transform: translateY(150%);
            transition: transform 0.5s cubic-bezier(0.16, 1, 0.3, 1);
        }

        .cookie-banner.visible {
            transform: translateY(0);
        }

        .cookie-text {
            font-size: 0.875rem;
            color: var(--text-secondary);
        }

        .cookie-actions {
            display: flex;
            gap: 12px;
        }

        .cookie-actions button {
            padding: 10px 20px;
            font-size: 0.875rem;
            font-weight: 500;
            border-radius: 4px;
            cursor: pointer;
            transition: background 0.3s;
        }

        .cookie-btn-accept {
            background-color: var(--text-primary);
            color: var(--bg-color);
        }

        .cookie-btn-accept:hover {
            background-color: var(--accent-color);
            color: var(--text-primary);
        }

        .cookie-btn-manage {
            background-color: transparent;
            color: var(--text-primary);
            border: 1px solid var(--border-color);
        }

        .cookie-btn-manage:hover {
            border-color: var(--text-secondary);
        }

        /* Responsive */
        @media (max-width: 1024px) {
            .hero-title { font-size: 3.5rem; }
            .principles-grid { grid-template-columns: 1fr; }
            .footer-ctas { grid-template-columns: 1fr; gap: 40px; }
            .work-card { min-width: 350px; }
        }

        @media (max-width: 768px) {
            .nav-links { display: none; }
            .mobile-menu-btn { display: flex; }
            .hero-title { font-size: 2.5rem; }
            .section-title { font-size: 2rem; }
            .footer-bottom { flex-direction: column; gap: 24px; align-items: flex-start; }
            .footer-links { flex-wrap: wrap; }
            .team-card { min-width: 280px; }
            .work-card { min-width: 280px; }
        }
    </style>
</head>
<body>

    <!-- Navigation -->
    <nav>
        <div class="logo">Leap Studio</div>
        <div class="nav-links">
            <a href="#insights">Insights</a>
            <a href="#work">Work</a>
            <a href="#services">Services</a>
            <a href="#culture">Culture</a>
            <a href="#mark">Make Your Mark</a>
            <a href="#contact">Contact Us</a>
        </div>
        <div class="nav-actions">
            <div class="lang-selector" id="language-toggle">
                <button class="lang-toggle" aria-haspopup="true" aria-expanded="false">
                    Global EN
                    <svg width="10" height="6" viewBox="0 0 10 6" fill="none" xmlns="http://www.w3.org/2000/svg">
                        <path d="M1 1L5 5L9 1" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/>
                    </svg>
                </button>
                <div class="lang-menu" id="lang-menu" role="menu">
                    <button role="menuitem">Global EN</button>
                    <button role="menuitem">France FR</button>
                    <button role="menuitem">China CN</button>
                </div>
            </div>
            <button class="mobile-menu-btn" aria-label="Menu">
                <span></span><span></span><span></span>
            </button>
        </div>
    </nav>

    <!-- Hero -->
    <header class="hero" id="hero-carousel">
        <!-- Slides -->
        <div class="hero-carousel" id="carousel-track">

            <div class="hero-slide active" style="background-image: url('https://images.unsplash.com/photo-1550751827-4bd374c3f58b?q=80&w=2070&auto=format&fit=crop');">
                <div class="container hero-content">
                    <h1 class="hero-title">Futurescape: Synthetic Realities</h1>
                    <p class="hero-desc">Welcome to the Futurescape. Discover trends and insights on the future of human-AI chemistry.</p>
                    <a href="#" class="cta-btn">Read the report</a>
                </div>
            </div>

            <div class="hero-slide" style="background-image: url('https://images.unsplash.com/photo-1485827404703-89b55fcc595e?q=80&w=2070&auto=format&fit=crop');">
                <div class="container hero-content">
                    <h1 class="hero-title">Designing Robots for Human Spaces</h1>
                    <p class="hero-desc">Meet "Aura," a concept from Leap Studio that offers a human-centered approach to physical AI.</p>
                    <a href="#" class="cta-btn">Explore the work</a>
                </div>
            </div>

            <div class="hero-slide" style="background-image: url('https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?q=80&w=2070&auto=format&fit=crop');">
                <div class="container hero-content">
                    <h1 class="hero-title">Amplifying Clinical Care with AI</h1>
                    <p class="hero-desc">Examining how service design helps experts understand the healthcare ecosystem.</p>
                    <a href="#" class="cta-btn">Explore now</a>
                </div>
            </div>

            <div class="hero-slide" style="background-image: url('https://images.unsplash.com/photo-1478737270239-2f02b77fc618?q=80&w=2070&auto=format&fit=crop');">
                <div class="container hero-content">
                    <h1 class="hero-title">Design Mind Leapcast Ep. 55</h1>
                    <p class="hero-desc">Peter Hallström, Global Head of Design at Lumina Health, discusses the evolution of product design and the role of design leadership.</p>
                    <a href="#" class="cta-btn">Listen now</a>
                </div>
            </div>

            <div class="hero-slide" style="background-image: url('https://images.unsplash.com/photo-1451187580459-43490279c0fa?q=80&w=2072&auto=format&fit=crop');">
                <div class="container hero-content">
                    <h1 class="hero-title">From Complexity to Clarity</h1>
                    <p class="hero-desc">Dive into new research on how CMOs can reclaim marketing to build competitive edge.</p>
                    <a href="#" class="cta-btn">Read the report</a>
                </div>
            </div>

        </div>

        <div class="hero-controls">
            <button id="hero-prev" aria-label="Previous slide">
                <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M15 18l-6-6 6-6"/></svg>
            </button>
            <button id="hero-next" aria-label="Next slide">
                <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M9 18l6-6-6-6"/></svg>
            </button>
        </div>
    </header>

    <!-- Global Studios Section -->
    <section class="section" id="team">
        <div class="container">
            <div class="section-header">
                <h2 class="section-title">Welcome to the studio</h2>
                <p class="section-subtitle">Meet the team making an impact for leading brands around the globe.</p>
            </div>

            <div class="region-tabs" id="team-region-toggle">
                <button class="region-tab active" data-region="na">North America</button>
                <button class="region-tab" data-region="asia">Asia</button>
                <button class="region-tab" data-region="europe">Europe</button>
                <button class="region-tab" data-region="oceania">Oceania</button>
            </div>

            <div id="team-member-carousel">
                <!-- North America -->
                <div class="region-content active" id="region-na">
                    <div class="team-grid">
                        <div class="team-card">
                            <div class="team-photo">
                                <img src="https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?w=500&auto=format&fit=crop" alt="Denice Alvarez">
                            </div>
                            <div class="team-info">
                                <p class="team-quote">As the Office Manager, I engage with teams from every discipline, and have learned so much through my day-to-day interactions with my fellow leapers.</p>
                                <div class="team-meta">
                                    <h4 class="team-name">Denice Alvarez</h4>
                                    <p class="team-title">Office Manager</p>
                                </div>
                                <a href="#" class="team-contact">Contact Leap Studio New York →</a>
                            </div>
                        </div>
                        <div class="team-card">
                            <div class="team-photo">
                                <img src="https://images.unsplash.com/photo-1560250097-0b93528c311a?w=500&auto=format&fit=crop" alt="Marco Bellini">
