    <script>
        // Hero Carousel
        const slides = document.querySelectorAll('.hero-slide');
        let currentSlide = 0;
        let slideInterval;

        function showSlide(index) {
            slides.forEach((s, i) => s.classList.toggle('active', i === index));
        }

        function nextSlide() {
            currentSlide = (currentSlide + 1) % slides.length;
            showSlide(currentSlide);
        }

        function prevSlide() {
            currentSlide = (currentSlide - 1 + slides.length) % slides.length;
            showSlide(currentSlide);
        }

        document.getElementById('hero-next').addEventListener('click', () => {
            nextSlide();
            resetInterval();
        });

        document.getElementById('hero-prev').addEventListener('click', () => {
            prevSlide();
            resetInterval();
        });

        function resetInterval() {
            clearInterval(slideInterval);
            slideInterval = setInterval(nextSlide, 6000);
        }
        resetInterval();

        // Language Toggle
        const langToggleBtn = document.querySelector('.lang-toggle');
        const langMenu = document.getElementById('lang-menu');

        langToggleBtn.addEventListener('click', (e) => {
            e.stopPropagation();
            const isExpanded = langToggleBtn.getAttribute('aria-expanded') === 'true';
            langToggleBtn.setAttribute('aria-expanded', !isExpanded);
            langMenu.classList.toggle('active');
        });

        document.addEventListener('click', (e) => {
            if (!langToggleBtn.contains(e.target) && !langMenu.contains(e.target)) {
                langMenu.classList.remove('active');
                langToggleBtn.setAttribute('aria-expanded', 'false');
            }
        });

        const langOptions = langMenu.querySelectorAll('button');
        langOptions.forEach(opt => {
            opt.addEventListener('click', () => {
                const text = opt.textContent;
                langToggleBtn.innerHTML = `${text} <svg width="10" height="6" viewBox="0 0 10 6" fill="none" xmlns="http://www.w3.org/2000/svg"><path d="M1 1L5 5L9 1" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>`;
                langMenu.classList.remove('active');
                langToggleBtn.setAttribute('aria-expanded', 'false');
            });
        });

        // Region Tabs
        const regionTabs = document.querySelectorAll('.region-tab');
        const regionContents = document.querySelectorAll('.region-content');

        regionTabs.forEach(tab => {
            tab.addEventListener('click', () => {
                regionTabs.forEach(t => t.classList.remove('active'));
                regionContents.forEach(c => c.classList.remove('active'));

                tab.classList.add('active');
                const targetId = `region-${tab.dataset.region}`;
                document.getElementById(targetId).classList.add('active');
            });
        });

        // Cookie Consent
        const cookieBanner = document.getElementById('cookie-consent');

        // Show banner after 2 seconds
        setTimeout(() => {
            if(!localStorage.getItem('cookies-accepted')) {
                cookieBanner.classList.add('visible');
            }
        }, 2000);

        function closeBanner() {
            cookieBanner.classList.remove('visible');
            localStorage.setItem('cookies-accepted', 'true');
        }

        document.getElementById('accept-cookies').addEventListener('click', closeBanner);
        document.getElementById('decline-cookies').addEventListener('click', closeBanner);
        document.getElementById('manage-cookies').addEventListener('click', closeBanner);

        document.getElementById('open-cookie-settings').addEventListener('click', (e) => {
            e.preventDefault();
            cookieBanner.classList.add('visible');
        });

    </script>
